style.css:
@-moz-document domain("roblox.com") {
/* ✅ Background Image from your video */
  body {
    background-image: url("https://chat.openai.com/mnt/data/roblox_custom_background.jpg");
    background-size: cover !important;
    background-attachment: fixed !important;
    background-repeat: no-repeat !important;
    background-position: center center !important;
  }

  /* ? Red UI sections */
  .rbx-navbar, .nav-menu, .left-col, .right-col, .rbx-header, 
  .menu-vertical, .container-main, .content, .section-content, 
  .rbx-main-content, .game-page, .game-detail-page, .footer-container,
  .avatar-editor-page, .dropdown-menu, .header-content {
    background-color: #ff0000 !important;
    color: black !important;
    border: none !important;
    backdrop-filter: blur(3px);
  }

  /* ? Buttons & Inputs */
  button, .btn-primary, .btn-control-sm, input, select, textarea {
    background-color: #ff0000 !important;
    color: black !important;
    border: 1px solid black !important;
  }

  /* ? Links and General Text */
  a, h1, h2, h3, h4, h5, h6, p, span, div, label, li, strong, em {
    color: black !important;
  }
}
